pragma solidity 0.8.28;

/*
 * AI-RECONSTRUCTED SOURCE. Not the original source code.
 *
 * Reconstructed 2026-10-30 00:30 UTC by Claude, from the deployed runtime
 * bytecode of 0x63e842b054bd624a465454d533c33f573e9c6fae on Ethereum mainnet.
 * Compiled with solc 0.8.28, --via-ir, optimizer 200 runs, evm cancun: the
 * runtime bytecode is byte-identical to on-chain, apart from the trailing
 * metadata hash. Contract and parameter names are guesses.
 *
 * What it is: a sweeper for an EIP-7702 delegated wallet. It is not used as a
 * standalone contract. Wallets point their code at it with a delegation
 * (0xef0100 || 0x63e8...6fae), so it runs as the wallet's own code, and only
 * the hardcoded `authorizedCaller` can call sweep / withdraw / callExecute.
 * The address 0x28c6c06298d514db089934071355e5743bf21d60, commonly labelled
 * as a "Binance 14" hot wallet, delegates to it as of this writing.
 *
 * How the delegation works, and what it implies:
 *   - An EIP-7702 delegation is only valid if the EOA's own private key signs
 *     an authorization tuple (chainId, delegate address, nonce). Whoever
 *     submits the transaction (here the sponsor, authorizedCaller) cannot
 *     create a delegation for an account without that signature.
 *   - Tx 0xad99264d5532ae0dd04b2004eebda05f25657e70dacb764f7ac8d4ccd051298b
 *     (block 26300753, 2026-10-29 20:20:59 UTC, type 4) carries 50
 *     authorizations, all delegating to this contract. Recovering the
 *     signatures shows ONE signer: 0x28c6c06298d514db089934071355e5743bf21d60
 *     signed all 50, with consecutive nonces 18914775 to 18914824.
 *   - So whoever assembled those 50 signatures had access to that single
 *     private key, or to the signing workflow that uses it. If the delegation
 *     was not intended by the wallet owner, this points to a compromise of
 *     the key or of the signing pipeline, not a bug in this or any other contract. The
 *     chain data alone cannot distinguish that from an authorized in-house
 *     action, so treat it as an inference, not a finding.
 *
 * "Robberies Could Be Prevented If Getaway Cars Were Slower"
 */

interface IERC20 {
    function balanceOf(address) external view returns (uint256);
    function transfer(address, uint256) external returns (bool);
}

interface IExecutor {
    function execute(address dest, uint256 value, bytes calldata data) external;
}

contract Target {
    address public constant authorizedCaller = 0x7C8601d4645b93cea45F71e118A729332e6B5CA0;

    error NotAuthorized();
    error TokenTransferFailed();
    error ETHTransferFailed();
    error NoCodeAtExecutor(address target);
    error ExecuteCallFailed(address target, bytes reason);

    event SweepItemFailed(address indexed token, uint8 code);

    modifier onlyAuthorized() {
        if (msg.sender != authorizedCaller) revert NotAuthorized();
        _;
    }

    receive() external payable {}

    function sweep(address payable to, address[] calldata tokens) external onlyAuthorized {
        for (uint256 i = 0; i < tokens.length; i++) {
            address token = tokens[i];
            if (token == address(0)) {
                uint256 bal = address(this).balance;
                if (bal > 1 ether) {
                    (bool ok,) = to.call{value: bal - 1 ether}("");
                    if (!ok) emit SweepItemFailed(token, 3);
                }
            } else {
                (bool s, bytes memory r) = token.staticcall(abi.encodeCall(IERC20.balanceOf, (address(this))));
                if (!s || r.length < 32) {
                    emit SweepItemFailed(token, 1);
                    continue;
                }
                uint256 bal = abi.decode(r, (uint256));
                if (bal > 0) {
                    (bool ok,) = token.call(abi.encodeCall(IERC20.transfer, (to, bal)));
                    if (!ok) emit SweepItemFailed(token, 2);
                }
            }
        }
    }

    function withdrawETH(address payable to, uint256 amount) external onlyAuthorized {
        _sendETH(to, amount);
    }

    function callExecute(address target, address payable to, uint256 value, bytes calldata data)
        external
        payable
        onlyAuthorized
        returns (bytes memory)
    {
        if (target.code.length == 0) revert NoCodeAtExecutor(target);
        (bool ok, bytes memory ret) =
            target.call{value: msg.value}(abi.encodeCall(IExecutor.execute, (to, value, data)));
        if (!ok) revert ExecuteCallFailed(target, ret);
        return ret;
    }

    function withdrawToken(address token, address to, uint256 amount) external onlyAuthorized {
        _sendToken(token, to, amount);
    }

    function _sendToken(address token, address to, uint256 amount) internal {
        if (amount == 0) return;
        (bool ok,) = token.call(abi.encodeCall(IERC20.transfer, (to, amount)));
        if (!ok) revert TokenTransferFailed();
    }

    function _sendETH(address payable to, uint256 amount) internal {
        if (amount == 0) return;
        (bool ok,) = to.call{value: amount}("");
        if (!ok) revert ETHTransferFailed();
    }
}
